"""Offline teaching material. Only completed exercises receive debrief content."""


def _lesson(concept, vocabulary, flow, watch, design, evidence, defense, retest, takeaway):
    return dict(
        learn=dict(concept=concept, vocabulary=vocabulary, flow=flow, watch=watch),
        debrief=dict(design=design, evidence=evidence, defense=defense,
                     retest=retest, takeaway=takeaway),
    )


