CATALOGUE = {'guided': GUIDED, 'expert': EXPERT, 'breakfix': BREAKFIX}


def lesson_view(workspace, exercise_id, completed):
    """Completion is supplied from persisted server progress, never a request flag."""
    lesson = CATALOGUE[workspace][exercise_id]
    return dict(learn=lesson['learn'], debrief=lesson['debrief'] if completed else None)
